         'markdown-it-task-lists',
         'mermaid',
         'yaml',
         '@shikijs/langs',
         'shiki/core',
         'shiki/engine/javascript',
         'shiki/langs',
         '@shikijs/themes/dark-plus',
         '@shikijs/themes/github-light-default',
